const { isLoading, isSaving, isChanged, save, resource } = useResource({
  key: userId,
  source: {
    fetch: () => api.getUser(userId),
    save: (d) => api.updateUser(userId, d),
  },
});

if (isLoading) return <Spinner />;
return (
  <>
    <EmailField resource={resource} />
    <button disabled={!isChanged || isSaving} onClick={() => save()}>Save</button>
  </>
);
